import numpy as np
A=np.array([[0,4,0],[0,4,2],[3,0,2]])
M=np.array([[1,0,0],[0,1,1],[1,1,0]],dtype=int)
for k in range(4):
 B=np.rot90(A,-k)
 for flip in (False,True):
  C=np.fliplr(B) if flip else B
  if np.array_equal(C!=0,M): print('match rotcw',k,'flip_lr',flip,'colored',C.tolist())

def rotcw(a): return [list(row) for row in zip(*a[::-1])]
def fliplr(a): return [row[::-1] for row in a]
A=[[0,4,0],[0,4,2],[3,0,2]]
M=[[0,1,0],[0,1,1],[1,1,0]]
for k in range(4):
 for flip in (False,True):
  C=[r[:] for r in A]
  for _ in range(k): C=rotcw(C)
  if flip:C=fliplr(C)
  if [[int(x!=0) for x in row] for row in C]==M: print(k,flip,C)

